INSERT INTO Products VALUES(N'А112Т4',N'Велосипед взрослый горный Slash Stream 27.5 колеса (2025) 17" Черный (162-172 см)',N'шт.',19775,N'ВелоСтрана',N'Slash',N'Велосипед взрослый горный',30,15,N'Горный велосипед Slash Stream 27.5 (2025) – легкий и надежный компаньон для поездок по пересеченной местности. Мощные шатуны интенсивно передают усилия мышц на вал каретки. ',N'1.jpg');
INSERT INTO Products VALUES(N'G843H5',N'Велосипед взрослый горный Slash Stream 27.5 колеса (2025) 19" Синий (172-182 см)',N'шт.',19791,N'ВелоСтрана',N'Slash',N'Велосипед взрослый горный',30,9,N'В комплектацию включены дисковые механические тормоза RPT DSC-310. Особый упор разработчики рамы данной модели сделали на увеличение прочности мест наибольшей нагрузки. ',N'2.jpg');
INSERT INTO Products VALUES(N'D325D4',N'Велосипед городской подростковый серый',N'шт.',9919,N'ЯндексМаркет',N'Shimano',N'Велосипед городской подростковый',5,12,N'Городской подростковый велосипед - идеальный выбор для активного образа жизни!
INSERT INTO Products VALUES(N'S432T5',N'Велосипед Skill Bike 3051, городской, 21 скорость, сталь, 29" колеса, черно-красный',N'шт.',16442,N'Скилс',N'Skill bike',N'Велосипед городской взрослый',15,15,N'SKILL BIKE модель 3051 - горный велосипед на спицах, обеспечивающий уверенную и комфортную езду как по городским улицам, так и по горной местности.',N'4.jpg');
INSERT INTO Products VALUES(N'F325D4',N'Велосипед Skillbike 3052, горный, складной, рама 17 дюймов, колеса 26 дюймов, 21 скорость',N'шт.',17985,N'Скилс',N'Skill bike',N'Велосипед взрослый горный',18,50,N'SKILL BIKE модель 3052 - велосипед складной, предназначен для тех, кто ценит комфорт, стиль и максимальную мобильность. Горный велосипед легко помещается в багажник и идеально подходит для активных поездок в городской суете.',N'5.jpg');
INSERT INTO Products VALUES(N'G432G6',N'Велосипед Skill Bike 3053, горный, двухподвесный, рама 17 дюймов, колеса 26 дюймов, 21 скорость',N'шт.',17621,N'Скилс',N'Skill bike',N'Велосипед взрослый горный',20,0,N'SKILL BIKE модель 3053 - горный велосипед на литых дисках, имеет амортизаторы как на переднем, так и на заднем колесе.',N'6.jpg');
INSERT INTO Products VALUES(N'H542F5',N'Велосипед MILANO M300, горный, для взрослых, 26", 7 скоростей',N'шт.',13509,N'ПерспективаГрупп',N'NEXT',N'Велосипед взрослый горный',4,5,N'Горный велосипед MILANO M300 с диаметром колес 26 дюйма подойдет для подростков и взрослых, без усилий позволит преодолевать любые непроходимые каменистые поверхности и зоны бездорожья.',N'7.jpg');
INSERT INTO Products VALUES(N'C346F5',N'Горный велосипед скоростной, колёса 24", рама - 14", черно-красный',N'шт.',15212,N'ПерспективаГрупп',N'
INSERT INTO Products VALUES(N'F256G6',N'26" Велосипед Fizard, 15" алюминий, дисковые тормоза, 21 скорость, серый',N'шт.',15126,N'ПерспективаГрупп',N'Fizard',N'Велосипед детский горный',25,3,N'Горный велосипед Fizard — надёжный универсальный маунтинбайк для города и бездорожья.',N'9.jpg');
